package model;
public class Doctor { private int doctorId,userId,departmentId,experienceYears; private String doctorName,specialization,departmentName,phone,email,availabilityStatus; private double consultationFee; public int getDoctorId(){return doctorId;} public void setDoctorId(int v){doctorId=v;} public int getUserId(){return userId;} public void setUserId(int v){userId=v;} public int getDepartmentId(){return departmentId;} public void setDepartmentId(int v){departmentId=v;} public int getExperienceYears(){return experienceYears;} public void setExperienceYears(int v){experienceYears=v;} public String getDoctorName(){return doctorName;} public void setDoctorName(String v){doctorName=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} public String getDepartmentName(){return departmentName;} public void setDepartmentName(String v){departmentName=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getAvailabilityStatus(){return availabilityStatus;} public void setAvailabilityStatus(String v){availabilityStatus=v;} public double getConsultationFee(){return consultationFee;} public void setConsultationFee(double v){consultationFee=v;} public String toString(){return doctorName+" ("+specialization+")";} }
